const temas = [
  'tendências de lucro em restaurantes',
  'erros de CMV em operações gastronômicas',
  'oportunidades de produtos digitais para donos de restaurante',
  'dores financeiras de pequenos e médios restaurantes',
  'automatizações com IA para gestão gastronômica',
  'como aumentar ticket médio no delivery',
  'redução de desperdício e impacto no CMV',
  'como precificar cardápio com base em dados',
  'gestão de equipe e produtividade na cozinha',
  'fidelização de clientes em restaurantes independentes'
];

const tema = temas[Math.floor(Math.random() * temas.length)];

return [{
  json: {
    titulo: tema,
    descricao: 'Pesquisa autônoma agendada pelo sistema — ' + new Date().toLocaleDateString('pt-BR'),
    modo_execucao: 'research_auto',
    prompt_openai: `Você é um analista estratégico de negócios digitais com foco em gastronomia, operação, IA e monetização.\n\nTEMA CENTRAL:\n${tema}\n\nCONTEXTO ADICIONAL:\nPesquisa autônoma diária do sistema MYO.\n\nSua missão:\n1. Encontrar 10 oportunidades de conteúdo ou produto\n2. Identificar dores de mercado\n3. Sugerir ângulos de posicionamento\n4. Sugerir quais ideias têm maior potencial de monetização\n5. Responder SOMENTE em JSON válido\n\nFormato obrigatório:\n{\n  "resumo_estrategico": "",\n  "dores": ["", ""],\n  "oportunidades": [{"titulo": "", "tipo": "conteudo|produto|servico", "potencial": 1, "justificativa": ""}],\n  "prioridade_recomendada": {"titulo": "", "motivo": ""}\n}`
  }
}];

function tryParse(text) {
  try { return JSON.parse(text); } catch(e) {
    const m = String(text).match(/\{[\s\S]*\}/);
    if (m) return JSON.parse(m[0]);
    throw new Error('Parse falhou');
  }
}
return items.map(item => {
  const raw = (item.json.message && item.json.message.content) || item.json.text || item.json.response || item.json.output || item.json.content || JSON.stringify(item.json);
  const parsed = tryParse(raw);
  const ops = parsed.oportunidades || [];
  const potenciais = ops.map(o => Number(o.potencial || 0));
  const score = potenciais.length
    ? Math.round(potenciais.reduce((a, b) => a + b, 0) / potenciais.length)
    : 5;
  return {
    json: {
      ...item.json,
      resultado_estruturado: parsed,
      saida_json: JSON.stringify(parsed, null, 2),
      score_ia: score,
      observacoes: 'Gerado automaticamente pelo agendador — ' + new Date().toLocaleDateString('pt-BR')
    }
  };
});
